body:
{
  "pains": [
    {
      "id": "pain:bounced-list",
      "statement": "The contacts Apollo calls verified still bounce on me, and I only find out after I've already sent.",
      "element": "b2b:functional:product_quality",
      "shape": {
        "surface": "Exported emails bounce and phone numbers ring the wrong person, or nobody.",
        "operational": "The rep reworks the list by hand, the sending domain eats the bounce penalty, and any pipeline number built on that list is wrong before the week ends.",
        "personal": "The rep looks sloppy in a reply-rate review for a list they did not build, and stops trusting any list handed to them."
      },
      "workflow": "Filtering in Apollo search, saving the list, pushing it to a sequence or exporting to CSV, then reading the bounce report the next morning.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "First send after a large export, when the hard-bounce count lands", "cites": ["src:14", "src:10"] },
        { "event": "A prospect replies that they left the company months ago", "cites": ["src:13", "src:16"] },
        { "event": "Quarterly list refresh when the team compares this quarter's data to last", "cites": ["src:28"] }
      ],
      "who_feels": ["end_user", "technical_evaluator", "economic_buyer"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "data is not perfect", "cites": ["src:14"] },
            { "situation": "when_it_bites", "verbatim": "some emails can bounce or be missing", "cites": ["src:14"] },
            { "situation": "venting", "verbatim": "contact data wasn't always accurate or up to date", "cites": ["src:13"] },
            { "situation": "when_it_bites", "verbatim": "we do not have 100% of the required information, especially email addresses and phone numbers. This has hindered progress with several companies", "cites": ["src:10"] },
            { "situation": "when_comparing", "verbatim": "I'll be honest, I dont like the absence of results, I do appreciate that the app does not falsify dat. At least To get me some data even if its not the decision maker, something to start with", "cites": ["src:30"] }
          ],
          "costs_them": "Hours a week scrubbing a list they already paid for, and a quota clock that keeps running while they do it.",
          "fears": "That the bounce rate gets read as a rep problem rather than a data problem, and shows up in their next one-on-one.",
          "dream_outcome": "Open a list, trust every row, and spend the morning talking to people instead of validating rows."
        },
        "technical_evaluator": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "Extremely expensive and most of the data is terrible and invalid", "cites": ["src:6"] },
            { "situation": "to_their_boss", "verbatim": "Some contact information is outdated and credit can runs out quickly with heavy", "cites": ["src:16"] }
          ],
          "costs_them": "They own CRM hygiene, so every stale record Apollo writes back becomes their cleanup queue.",
          "fears": "That leadership's pipeline reporting is built on records they privately know are wrong.",
          "dream_outcome": "A single source they can vouch for in a leadership meeting without adding a caveat."
        },
        "economic_buyer": {
          "says": [
            { "situation": "when_refusing", "verbatim": "Just a money grab on old outdated and junk data", "cites": ["src:6"] }
          ],
          "costs_them": "Seat spend against a list the team does not believe in, plus the reps' time re-verifying it.",
          "fears": "That the whole outbound number is fiction and they find out at board review.",
          "dream_outcome": "Reply rate moves because the list is real, not because the team dialed harder."
        }
      },
      "segments": ["seg:smb", "seg:midmarket", "seg:revops"],
      "feature_ref": "feat:waterfall",
      "cites": ["src:13", "src:14", "src:16", "src:10", "src:6", "src:30", "src:28"]
    },
    {
      "id": "pain:credit-meter",
      "statement": "I already paid for the seat, and now every single thing I touch costs another credit.",
      "element": "b2b:ease_of_doing_business:transparency",
      "shape": {
        "surface": "Reveals, enrichments and exports all draw down a credit balance that runs out mid-month.",
        "operational": "Reps ration their own prospecting, stop enriching marginal accounts, and the team's real cost per contact is unknowable until the cycle closes.",
        "personal": "The rep feels metered inside a tool they were told was theirs, and starts hoarding credits instead of working the territory."
      },
      "workflow": "Revealing an email or phone in Apollo search or the Chrome extension, watching the credit counter drop, then hitting the wall in week three of the billing cycle.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Credit balance runs dry mid-cycle during a push", "cites": ["src:16", "src:15"] },
        { "event": "Renewal quote arrives and unused credits have been forfeited", "cites": ["src:26"] },
        { "event": "A rep asks the manager to buy more credits to finish a campaign", "cites": ["src:7"] }
      ],
      "who_feels": ["end_user", "economic_buyer", "technical_evaluator"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "Some contact information is outdated and credit can runs out quickly with heavy", "cites": ["src:16"] },
            { "situation": "venting", "verbatim": "have to stay organized with your credits to maximize value", "cites": ["src:15"] },
            { "situation": "when_comparing", "verbatim": "Unclear pricing, forced waterfall verification, slow email access", "cites": ["src:18"] }
          ],
          "costs_them": "Prospecting throttled by an internal budget they do not control, in the middle of a quota month.",
          "fears": "Burning the team's credits on a list that turns out to be junk and being the one who wasted them.",
          "dream_outcome": "Prospect as hard as the day allows without doing arithmetic on every reveal."
        },
        "economic_buyer": {
          "says": [
            { "situation": "when_refusing", "verbatim": "Charges you credits for any action you take inside which makes no sense because you've already paid an arm and a leg for the subscription", "cites": ["src:6"] },
            { "situation": "when_comparing", "verbatim": "Throttling and limits on their free plan makes it unusable and their paid plan is ridiculously expensive. Even their paid basic plan is heavily throttled and restricted.", "cites": ["src:7"] }
          ],
          "costs_them": "A line item that is a seat price plus an unpredictable consumption bill on top of it.",
          "fears": "Signing an annual number and then being asked for overage money every quarter.",
          "dream_outcome": "One number per rep per year that they can defend to finance without footnotes."
        }
      },
      "segments": ["seg:smb", "seg:midmarket", "seg:revops"],
      "feature_ref": null,
      "feature_note": "Nothing in brain/company removes the credit meter; waterfall enrichment spends more of it, not less. What would kill it is flat per-seat access with no consumption draw, or credits that roll over.",
      "cites": ["src:6", "src:7", "src:15", "src:16", "src:18", "src:26"]
    },
    {
      "id": "pain:deliverability-decay",
      "statement": "I have great data and a full sequence and almost nobody replies, and I can't tell if it's the list or the inbox.",
      "element": "b2b:functional:improved_top_line",
      "shape": {
        "surface": "Reply rates on sequences sit near zero even with a clean, well-filtered list.",
        "operational": "The team keeps buying and warming new domains to stay out of spam, which resets any sender reputation they had built and makes campaign results impossible to read.",
        "personal": "The rep cannot separate their own message quality from inbox placement, so they stop learning from the numbers."
      },
      "workflow": "Launching a sequence from the Apollo workspace off a saved list, then watching opens and replies in the campaign report and not being able to tell placement from message.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "A campaign with good data returns almost no replies", "cites": ["src:2"] },
        { "event": "A sending domain gets flagged and the team spins up a fresh one", "cites": ["src:23"] },
        { "event": "Warmup settings turn out to have been wrong the whole time", "cites": ["src:5"] }
      ],
      "who_feels": ["end_user", "champion", "economic_buyer"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "The main drawback we've experienced is the low response rate to email campaigns, which can make it difficult to determine how effective the outreach is, despite having access to a strong database of contacts.", "cites": ["src:2"] }
          ],
          "costs_them": "A full sequence's worth of work with no signal back about what to change.",
          "fears": "That the whole channel is dead and their job depends on it.",
          "dream_outcome": "A reply rate they can attribute to the message, so they can actually iterate."
        },
        "champion": {
          "says": [
            { "situation": "venting", "verbatim": "There's a ton of leads agencies that gobble these up sending out tens of thousands of emails every day using the latest incarnation of this spamware, creating new domains and warming them up with fake emails to each other and now using LLMs to \"personalize\" the emails (i.e. the \"AI\") all in the attempt to evade spam filters.", "cites": ["src:23"] },
            { "situation": "when_comparing", "verbatim": "Tools like Clay and Apollo are often misused for spammy cold outreach—which rarely works.", "cites": ["src:24"] }
          ],
          "costs_them": "Recurring domain and warmup spend just to hold the channel steady.",
          "fears": "Having championed a motion that the market has already learned to filter out.",
          "dream_outcome": "Outbound that lands because it is wanted, not because it evaded a filter."
        },
        "economic_buyer": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "There's a new one every day because the last one got banned/isn't effective anymore.", "cites": ["src:23"] }
          ],
          "costs_them": "Seat spend on a channel whose yield keeps falling regardless of tooling.",
          "fears": "Paying per seat for a motion that is structurally in decline.",
          "dream_outcome": "Evidence that the channel still produces meetings at a cost they can justify."
        }
      },
      "segments": ["seg:smb", "seg:midmarket"],
      "feature_ref": null,
      "feature_note": "GTM Harness writes more outreach, which does not fix placement. What kills this is inbox placement reporting the buyer can trust, separating deliverability from message quality in the campaign report.",
      "cites": ["src:2", "src:23", "src:24", "src:5"]
    },
    {
      "id": "pain:sequence-misfire",
      "statement": "I set it to send twenty-five and it dumped the whole seven hundred, and then I couldn't stop it.",
      "element": "b2b:ease_of_doing_business:risk_reduction",
      "shape": {
        "surface": "Sequence sending behaviour does not match what the rep configured, and there is no reliable stop.",
        "operational": "A misfire burns a real list and a real sending domain in one action, and the damage cannot be undone.",
        "personal": "The rep loses their nerve with the tool and starts sending smaller batches by hand, which is the exact work the platform was bought to remove."
      },
      "workflow": "Adding contacts to a sequence in the Apollo workspace, setting a daily send limit, hitting activate, then trying to deactivate when the send count looks wrong.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        { "event": "A test batch sends to the full list instead of the limit set", "cites": ["src:11"] },
        { "event": "AI-generated sends fail repeatedly across attempts", "cites": ["src:12"] }
      ],
      "who_feels": ["end_user", "champion"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "It's utterly impossible to send emails... The damn thing adds all 700 at once and sends them, and then won't let me deactivate... then takes the 25 I wanted to send, only sends 2, and then schedules the other 23 for a undisclosed time.", "cites": ["src:11"] },
            { "situation": "when_it_bites", "verbatim": "This ai system is supposed to send emails for you... However, it failed over and over and over again... It's buggy. It does NOT work.", "cites": ["src:12"] }
          ],
          "costs_them": "A list they cannot re-approach and a domain reputation hit, from one click.",
          "fears": "Sending something wrong to a named account and having to explain it to the AE who owns it.",
          "dream_outcome": "Hit send and know exactly what went out, to whom, and when."
        },
        "champion": {
          "says": [
            { "situation": "to_their_boss", "verbatim": "It's buggy. It does NOT work.", "cites": ["src:12"] }
          ],
          "costs_them": "Credibility with the team they told to move their outreach into this tool.",
          "fears": "A rep blasting a strategic account list during a live deal cycle.",
          "dream_outcome": "Send limits and a kill switch that behave the way the settings say they do."
        }
      },
      "segments": ["seg:smb", "seg:midmarket"],
      "feature_ref": "feat:workspace",
      "cites": ["src:11", "src:12"]
    },
    {
      "id": "pain:setup-maze",
      "statement": "Connecting a mailbox and warming it up took me days and several support agents, and I work in tech.",
      "element": "b2b:ease_of_doing_business:simplification",
      "shape": {
        "surface": "Mailbox connection, warmup and sending settings are a wall of toggles with no clear finished state.",
        "operational": "Days of ramp before the first send, and support routes the buyer to documentation rather than resolving it.",
        "personal": "A technically confident buyer feels stupid, which is a bad first week with a tool they just paid for."
      },
      "workflow": "First-week setup: linking Google or Microsoft mailboxes, configuring warmup, and trying to confirm from the settings screen whether warmup is actually running.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Onboarding stalls and support escalates to engineering", "cites": ["src:3"] },
        { "event": "Buyer cannot tell from the interface whether warmup is complete", "cites": ["src:5"] },
        { "event": "A new rep is added to the team and has to repeat the whole setup", "cites": ["src:34"] }
      ],
      "who_feels": ["end_user", "champion", "technical_evaluator"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "There is nothing intuitive in the set up and I have worked in technology for years. Onboarding process needs better training/instruction.", "cites": ["src:3"] },
            { "situation": "when_it_bites", "verbatim": "Load of toggles and buttons with no clear purpose make it impossible to figure out is your warmup all set or you need to keep on reading instructions.", "cites": ["src:5"] },
            { "situation": "venting", "verbatim": "UI can feel slightly cluttered, and initial setup takes some time", "cites": ["src:34"] }
          ],
          "costs_them": "Days of paid seat time before a single email leaves.",
          "fears": "Sending on a half-warmed mailbox and torching the domain without knowing.",
          "dream_outcome": "Connect the mailbox, see one green state that says ready, and send."
        },
        "champion": {
          "says": [
            { "situation": "to_their_boss", "verbatim": "I went through several support agents all who told me that engineering would have to get involved.", "cites": ["src:3"] },
            { "situation": "when_refusing", "verbatim": "non-existent support - you are sent to read tons of docs whenever you have a simple question", "cites": ["src:5"] }
          ],
          "costs_them": "Their own hours unblocking reps on a tool they sponsored.",
          "fears": "Slow ramp making the rollout look like a bad call before it has produced anything.",
          "dream_outcome": "A new rep live and sending on day one without a support ticket."
        }
      },
      "segments": ["seg:smb", "seg:midmarket"],
      "feature_ref": "feat:workspace",
      "cites": ["src:3", "src:5", "src:34"]
    },
    {
      "id": "pain:click-weight",
      "statement": "The pages load slow and it takes too many clicks to get to one contact, and I do this three hundred times a day.",
      "element": "b2b:ease_of_doing_business:time_savings",
      "shape": {
        "surface": "Heavy page loads, too many windows, navigation that is not where the rep expects it.",
        "operational": "Seconds of friction multiplied across hundreds of daily records becomes a real share of the selling day.",
        "personal": "A rep whose whole day is repetition feels the interface fighting them, and drifts back to LinkedIn tabs and spreadsheets."
      },
      "workflow": "The repeated loop of Apollo search, opening a contact, revealing details, pushing to a list or sequence, and the Chrome extension on a LinkedIn profile.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "A high-volume prospecting day where interface latency compounds", "cites": ["src:9"] },
        { "event": "A new user opens the workspace for the first time", "cites": ["src:17", "src:35"] },
        { "event": "The session drops mid-task and work is lost", "cites": ["src:10"] }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "Data is fine.. but UX is very bad.. heavy loading pages to many windows with slow loading, too many clicks to reach data many navigation buttons seems to be not in the logical place", "cites": ["src:9"] },
            { "situation": "when_it_bites", "verbatim": "ui and experience is overwhelming", "cites": ["src:17"] },
            { "situation": "when_looking", "verbatim": "interface can feel a bit overwhelming at first", "cites": ["src:35"] },
            { "situation": "when_it_bites", "verbatim": "Occasionally the user session closes unexpectedly", "cites": ["src:10"] },
            { "situation": "when_refusing", "verbatim": "Same bloatware as Salesforce and Hubspot, useless search and AI assistant", "cites": ["src:5"] }
          ],
          "costs_them": "A meaningful slice of the selling day spent waiting on the tool rather than talking to buyers.",
          "fears": "Missing activity targets because of the tool, and having it counted against them anyway.",
          "dream_outcome": "One screen, one click to the contact, no waiting."
        }
      },
      "segments": ["seg:smb", "seg:midmarket"],
      "feature_ref": "feat:extension",
      "cites": ["src:9", "src:17", "src:35", "src:10", "src:5"]
    },
    {
      "id": "pain:provenance-risk",
      "statement": "Nobody told me that plugging our CRM in means our customer list becomes everyone else's prospecting list.",
      "element": "b2b:table_stakes:regulatory_compliance",
      "shape": {
        "surface": "Records the company loaded for its own enrichment turn up in other Apollo customers' searches.",
        "operational": "The company becomes the source of a disclosure it never reviewed, with a legal basis it likely cannot document, and the opt-out path is a setting most buyers never find.",
        "personal": "Whoever connected the integration owns an incident they did not know they were creating."
      },
      "workflow": "Connecting Salesforce or HubSpot to Apollo for enrichment, or installing the mailbox extension, and never seeing the contributor-network data-sharing setting in the process.",
      "type": "latent",
      "confidence": "high",
      "revealed_by": "feat:data",
      "triggers": [
        { "event": "A customer receives cold mail on an address only that company held", "cites": ["src:19"] },
        { "event": "Legal or a customer asks where the contact data came from", "cites": ["src:21"] },
        { "event": "A data subject files a removal request and the record persists", "cites": ["src:29"] }
      ],
      "who_feels": ["technical_evaluator", "blocker", "economic_buyer"],
      "by_role": {
        "technical_evaluator": {
          "says": [
            { "situation": "when_it_bites", "verbatim": "Everyone in this thread suggesting a \"data leak\" or \"compromise\" is totally missing the fact that this is how Apollo works. This is often times overlooked by Apollo customers themselves. You have to opt out of customer data sharing (and in doing so lose out on the value of the product)", "cites": ["src:20"] },
            { "situation": "when_comparing", "verbatim": "Apollo's customer data sharing adds any information BrowserStack send to Apollo to the person's profile with Apollo, accessible to all Apollo customers.", "cites": ["src:19"] },
            { "situation": "when_it_bites", "verbatim": "It costs a credit for a salesperson to enrich the data of someone they're trying to contact. There are 2 ways to gain credits: 1 - cash; 2 - the salesperson installs a plugin in their inbox and it scrapes all contact info in the inbox.", "cites": ["src:25"] }
          ],
          "costs_them": "An audit they have to run after the fact, across every integration and extension a rep ever installed.",
          "fears": "Discovering the exposure from a customer's complaint rather than from their own review.",
          "dream_outcome": "Enrichment that reads without contributing, with a written record of what left the building."
        },
        "blocker": {
          "says": [
            { "situation": "when_refusing", "verbatim": "you need to make sure you actually have the right legal basis for putting customer details into your CRM, and your support database almost certainly does not hold appropriate data!", "cites": ["src:21"] },
            { "situation": "when_refusing", "verbatim": "Steals and sells your data without consent. You get bombarded with junk email. They claim to remove your details but don't at all. Sham of an organisation!", "cites": ["src:29"] }
          ],
          "costs_them": "Owning a regulatory exposure created by a sales tool procurement they may not have reviewed.",
          "fears": "A GDPR complaint traced back to their own company as the source.",
          "dream_outcome": "Being able to say exactly what the vendor does with company data, and prove it."
        }
      },
      "segments": ["seg:revops", "seg:midmarket"],
      "feature_ref": null,
      "feature_note": "Apollo Data is what creates this, not what fixes it. What kills it is read-only enrichment with contribution off by default and an exportable log of what the company's connection shared.",
      "cites": ["src:19", "src:20", "src:21", "src:25", "src:29"]
    },
    {
      "id": "pain:seat-lockin",
      "statement": "My team shrank and I'm still paying for the seats until the contract renews.",
      "element": "b2b:ease_of_doing_business:flexibility",
      "shape": {
        "surface": "Seat count cannot be reduced mid-term, credits do not roll over, and cancellation needs advance written notice.",
        "operational": "The spend is fixed against a headcount that moves, so every departure or hiring freeze turns into dead budget until renewal.",
        "personal": "The leader who signed it has to defend a bill for people who no longer work there."
      },
      "workflow": "Annual contract signing, then the quarterly seat reconciliation when reps churn or the team is cut, and the 30-day notice window before auto-renewal.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        { "event": "A rep leaves and the seat cannot be removed until renewal", "cites": ["src:26"] },
        { "event": "The renewal auto-triggers because the notice window was missed", "cites": ["src:22", "src:26"] },
        { "event": "Unused credits are forfeited at the end of the billing cycle", "cites": ["src:26"] }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            { "situation": "when_refusing", "verbatim": "Scammy companies like apollo.io follow dark patterns to provide several hoops before cancellation, refuse refunds and one click subscribe into an absurd annual contract.", "cites": ["src:22"] },
            { "situation": "when_comparing", "verbatim": "Seat reductions are also not permitted mid-contract.", "cites": ["src:26"] },
            { "situation": "when_it_bites", "verbatim": "Credits expire at the end of your billing cycle...Unused credits are forfeited with no refund or extension.", "cites": ["src:26"] }
          ],
          "costs_them": "Budget locked against headcount that has already changed, plus forfeited credits at each cycle.",
          "fears": "Signing again and being trapped for another twelve months on a tool the team has cooled on.",
          "dream_outcome": "Pay for the seats actually in use this month, and leave without a negotiation."
        }
      },
      "segments": ["seg:smb", "seg:midmarket"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company addresses commercial terms. What kills this is monthly seat true-down and credit rollover.",
      "cites": ["src:22", "src:26"]
    },
    {
      "id": "pain:account-lockout",
      "statement": "I got locked out with a pile of paid credits sitting in the account and nobody will tell me why.",
      "element": "b2b:ease_of_doing_business:availability",
      "shape": {
        "surface": "Accounts are suspended or banned with an unspecified usage reason, while paid credits stay stranded inside.",
        "operational": "Outbound stops for that seat or that whole workspace with no forecastable restore date, and appeals go nowhere.",
        "personal": "The buyer feels they are arguing with a wall about money they already spent."
      },
      "workflow": "Normal daily use of the Apollo workspace, until a login or verification failure locks the seat and support gives a policy answer instead of a cause.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        { "event": "Account suspended citing unspecified product usage behaviour", "cites": ["src:32"] },
        { "event": "Login or verification failure blocks access to purchased credits", "cites": ["src:8"] },
        { "event": "Support loops without resolving the underlying issue", "cites": ["src:1"] }
      ],
      "who_feels": ["end_user", "economic_buyer"],
      "by_role": {
        "end_user": {
          "says": [
            { "situation": "venting", "verbatim": "I've spent hours going in circles with this thing. No way to share feedback directly, so I'm venting here. Buyer beware.", "cites": ["src:1"] }
          ],
          "costs_them": "Selling days lost with no way to escalate.",
          "fears": "Losing a live sequence and the pipeline attached to it.",
          "dream_outcome": "A named human who can say what happened and restore access the same day."
        },
        "economic_buyer": {
          "says": [
            { "situation": "when_refusing", "verbatim": "Permanently locked out of my account and no way of getting back in with the value of credits on the account being very substancial.", "cites": ["src:8"] },
            { "situation": "when_refusing", "verbatim": "I see value in the product but it's completely useless when you get locked out of your account... stay clear.", "cites": ["src:8"] },
            { "situation": "when_it_bites", "verbatim": "the process was rigid, opaque, and deeply dismissive of a business user's legitimate concerns.", "cites": ["src:32"] }
          ],
          "costs_them": "Prepaid credits written off and a team idled with no restore date.",
          "fears": "Building the outbound motion on a vendor that can switch it off without explanation.",
          "dream_outcome": "A support path with a human and a stated reason, matched to what they are paying."
        }
      },
      "segments": ["seg:smb", "seg:midmarket"],
      "feature_ref": null,
